{"code":"import { runSql } from '../servers/earnings/index.js';

// Pegar a receita do trimestre mais antigo e mais recente de cada empresa
const symbols = ['AAPL', 'AMZN', 'GOOGL', 'META', 'MSFT', 'ORCL', 'AMD', 'CRM', 'INTU', 'NVDA'];

const results = [];

for (const sym of symbols) {
  // Último trimestre
  const latest = await runSql({ sql: `
    SELECT period_end, revenue
    FROM v_quarter
    WHERE symbol = '${sym}'
    ORDER BY period_end DESC
    LIMIT 1
  `});

  // Primeiro trimestre
  const oldest = await runSql({ sql: `
    SELECT period_end, revenue
    FROM v_quarter
    WHERE symbol = '${sym}'
    ORDER BY period_end ASC
    LIMIT 1
  `});

  const revLatest = latest.rows[0].revenue;
  const revOldest = oldest.rows[0].revenue;
  const endDate = new Date(latest.rows[0].period_end);
  const startDate = new Date(oldest.rows[0].period_end);

  const daysBetween = (endDate - startDate) / (1000 * 60 * 60 * 24);
  const years = daysBetween / 365.25;

  const cagr = (Math.pow(revLatest / revOldest, 1 / years) - 1) * 100;

  results.push({
    symbol: sym,
    revOldest: revOldest,
    revLatest: revLatest,
    startDate: oldest.rows[0].period_end,
    endDate: latest.rows[0].period_end,
    days: daysBetween,
    years: years,
    cagr: cagr
  });
}

results.sort((a, b) => b.cagr - a.cagr);

console.log(JSON.stringify(results, null, 2));
"}

